import { HttpError } from '../server.js';
import type { Adapter } from './index.js';
import { buyzSync, buyzTest, type Run } from './buyzQueries.js';

// Buyz operational data through dashboard_ops.php on the Buyz server (generated by scripts/gen-buyz-php.mjs).
// Used when the database port is closed to the outside: the PHP file runs the same named, read-only queries
// against the local database and returns rows as JSON. Auth: X-Api-Key = the key set in that file.

const ALLOWED_HOST = /(^|\.)buyz\.co\.il$/i;

function endpoint(config: Record<string, string>) {
  let u: URL;
  try { u = new URL((config.url || 'https://buyz.co.il/api/dashboard_ops.php').trim()); } catch { throw new HttpError(400, 'כתובת לא תקינה'); }
  if (u.protocol !== 'https:' || !ALLOWED_HOST.test(u.hostname)) throw new HttpError(400, 'הכתובת חייבת להיות https ב־buyz.co.il');
  return u.toString();
}

const runner = (config: Record<string, string>, key: string): Run => async (name, params = []) => {
  const r = await fetch(endpoint(config), {
    method: 'POST', signal: AbortSignal.timeout(20000),
    headers: { 'content-type': 'application/json', accept: 'application/json', 'x-api-key': key },
    body: JSON.stringify({ q: name, p: params }),
  });
  const j: any = await r.json().catch(() => null);
  if (r.status === 401 || r.status === 403) throw new HttpError(424, 'Buyz דחתה את המפתח של קובץ הנתונים');
  if (r.status === 404) throw new HttpError(424, 'הקובץ dashboard_ops.php לא נמצא בשרת של Buyz');
  if (!r.ok || !j?.ok) throw new HttpError(502, `Buyz: ${String(j?.error ?? r.status).slice(0, 200)}`);
  return Array.isArray(j.rows) ? j.rows : [];
};

export const buyzops: Adapter = {
  test: (config, secret) => buyzTest(runner(config, secret), config.slug || 'ospa'),
  sync: (config, secret) => buyzSync(runner(config, secret), config.slug || 'ospa'),
};
